def ensure(*pkgs):
    """Installiert fehlende Pakete automatisch. pkgs = (pip-Name, Modulname)."""
    if getattr(sys, "frozen", False):
        return
    import importlib.util
    missing = [p for p, mod in pkgs if importlib.util.find_spec(mod) is None]
    if missing:
        print("Installiere fehlende Pakete:", ", ".join(missing), flush=True)
        try:
            subprocess.check_call([sys.executable, "-m", "pip", "install", *missing])
        except subprocess.CalledProcessError:
            raise SystemExit("Paket-Installation fehlgeschlagen. Prüfe deine Internetverbindung.")


# ═════════════════════════ LIZENZSERVER ═════════════════════════
KEY_RE = re.compile(r"^[A-Z0-9]{4}(-[A-Z0-9]{4}){3}$")
KEY_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"


def db():
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    return con


def init_db():
    with db() as c:
        c.execute(
            """CREATE TABLE IF NOT EXISTS licenses(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                key TEXT UNIQUE NOT NULL,
                note TEXT DEFAULT '',
                created_at INTEGER NOT NULL,
                expires_at INTEGER,
                hwid TEXT,
                revoked INTEGER NOT NULL DEFAULT 0,
                last_seen INTEGER)"""
        )
        c.execute(
            """CREATE TABLE IF NOT EXISTS users(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                name TEXT NOT NULL,
                avatar TEXT DEFAULT '',
                discord TEXT DEFAULT '',
                license_id INTEGER,
                created_at INTEGER NOT NULL,
                last_login INTEGER)"""
        )
        c.execute(
            """CREATE TABLE IF NOT EXISTS registration_challenges(
                id TEXT PRIMARY KEY,
                answer_hash TEXT NOT NULL,
                attempts INTEGER NOT NULL DEFAULT 0,
                created_at INTEGER NOT NULL,
                expires_at INTEGER NOT NULL)"""
        )
        c.execute("DROP TABLE IF EXISTS pending_registrations")
        c.execute(
            """CREATE TABLE IF NOT EXISTS admins(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE COLLATE NOCASE NOT NULL,
                password_hash TEXT NOT NULL,
                is_active INTEGER NOT NULL DEFAULT 1,
                is_superadmin INTEGER NOT NULL DEFAULT 0,
                created_at INTEGER NOT NULL)"""
        )
        admin_columns = {row["name"] for row in c.execute("PRAGMA table_info(admins)").fetchall()}
        if "is_superadmin" not in admin_columns:
            c.execute("ALTER TABLE admins ADD COLUMN is_superadmin INTEGER NOT NULL DEFAULT 0")
        user_columns = {row["name"] for row in c.execute("PRAGMA table_info(users)").fetchall()}
        if "is_active" not in user_columns:
            c.execute("ALTER TABLE users ADD COLUMN is_active INTEGER NOT NULL DEFAULT 1")


def new_key():
    return "-".join("".join(secrets.choice(KEY_ALPHABET) for _ in range(4)) for _ in range(4))


def fmt_ts(ts):
    return time.strftime("%d.%m.%Y %H:%M", time.localtime(ts)) if ts else "–"


