def create_app(admin_password):
    from functools import wraps

    from flask import (Flask, abort, g, jsonify, redirect, render_template_string,
                       request, session)
    from werkzeug.exceptions import HTTPException

    init_db()  # Tabelle wird bei JEDEM Start angelegt, falls sie fehlt
    app = Flask(__name__)
    app.secret_key = os.environ.get("SECRET_KEY") or secrets.token_hex(32)
    app.config.update(SESSION_COOKIE_HTTPONLY=True, SESSION_COOKIE_SAMESITE="Strict")
    hits = {}
    def rate_limited(name):
        now = time.time()
        lst = [t for t in hits.get(name, []) if now - t < 60]
        lst.append(now)
        hits[name] = lst
        return len(lst) > 20

    # ───── CORS Support für externe / lokale Websites ─────
    @app.after_request
    def add_cors(resp):
        resp.headers["Access-Control-Allow-Origin"] = "*"
        resp.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization, X-Requested-With"
        resp.headers["Access-Control-Allow-Methods"] = "GET, POST, PUT, DELETE, OPTIONS, PATCH"
        return resp

    @app.route("/api/<path:path>", methods=["OPTIONS"])
    def api_cors_options(path):
        return ("", 204)

    # ───── Token Generierung & Validierung ─────
    def make_token(username):
        exp = int(time.time()) + 7 * 86400  # 7 Tage gültig
        raw = f"{username}:{exp}"
        sig = hmac.new(app.secret_key.encode(), raw.encode(), hashlib.sha256).hexdigest()
        return f"{raw}:{sig}"

    def verify_token(tok):
        if not tok:
            return False
        parts = tok.split(":")
        if len(parts) != 3:
            return False
        user, exp_str, sig = parts
        try:
            exp = int(exp_str)
        except ValueError:
            return False
        if exp < time.time():
            return False
        expected_sig = hmac.new(app.secret_key.encode(), f"{user}:{exp}".encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected_sig):
            return None
        with db() as c:
            admin = c.execute("SELECT is_active FROM admins WHERE username=? COLLATE NOCASE", (user,)).fetchone()
        return user if admin and admin["is_active"] else None

    # ───── Benutzer-Passwort & Auth Helpers ─────
    def hash_password(password):
        salt = secrets.token_hex(16)
        h = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), 100000).hex()
        return f"{salt}:{h}"

    def verify_password(password, stored_hash):
        if not stored_hash or ":" not in stored_hash:
            return False
        salt, h = stored_hash.split(":", 1)
        check = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), 100000).hex()
        return hmac.compare_digest(check, h)

    def registration_challenge_hash(challenge_id, answer):
        raw = f"registration-challenge:{challenge_id}:{answer}"
        return hmac.new(app.secret_key.encode(), raw.encode(), hashlib.sha256).hexdigest()

    # Beim ersten Start wird der bisherige ADMIN_USER/ADMIN_PASSWORD als
    # erster Datenbank-Admin übernommen. Bestehende Konten bleiben erhalten.
    with db() as c:
        has_superadmin = c.execute("SELECT 1 FROM admins WHERE is_superadmin=1 LIMIT 1").fetchone()
        if not has_superadmin:
            legacy_admin = c.execute("SELECT id FROM admins WHERE username=? COLLATE NOCASE", (ADMIN_USER,)).fetchone()
            if legacy_admin:
                c.execute("UPDATE admins SET is_superadmin=1 WHERE id=?", (legacy_admin["id"],))
            else:
                c.execute(
                    "INSERT INTO admins(username,password_hash,is_active,is_superadmin,created_at) VALUES(?,?,1,1,?)",
                    (ADMIN_USER, hash_password(admin_password), int(time.time())),
                )

    def make_user_token(uid):
        exp = int(time.time()) + 30 * 86400  # 30 Tage gültig
        raw = f"usr:{uid}:{exp}"
        sig = hmac.new(app.secret_key.encode(), raw.encode(), hashlib.sha256).hexdigest()
        return f"{raw}:{sig}"

    def verify_user_token(tok):
        if not tok or not tok.startswith("usr:"):
            return None
        parts = tok.split(":")
        if len(parts) != 4:
            return None
        _, uid_str, exp_str, sig = parts
        try:
            uid, exp = int(uid_str), int(exp_str)
        except ValueError:
            return None
        if exp < time.time():
            return None
        expected = hmac.new(app.secret_key.encode(), f"usr:{uid}:{exp}".encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return None
        return uid

    def api_user_required(fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            auth = request.headers.get("Authorization", "")
            tok = auth.replace("Bearer ", "").strip() if auth.startswith("Bearer ") else None
            uid = verify_user_token(tok)
            if not uid:
                return jsonify(success=False, error="Nicht eingeloggt oder Sitzung abgelaufen."), 401
            with db() as c:
                u = c.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()
            if not u:
                return jsonify(success=False, error="Benutzerkonto nicht gefunden."), 404
            if not u["is_active"]:
                return jsonify(success=False, error="Dein Konto wurde vom Administrator gesperrt."), 403
            return fn(dict(u), *a, **kw)
        return wrapper

    def serialize_user(u):
        lic = None
        if u.get("license_id"):
            with db() as c:
                l = c.execute("SELECT * FROM licenses WHERE id=?", (u["license_id"],)).fetchone()
            if l:
                now = int(time.time())
                if l["revoked"]:
                    st = "gesperrt"
                elif l["expires_at"] and l["expires_at"] < now:
                    st = "abgelaufen"
                else:
                    st = "aktiv"
                lic = {
                    "id": l["id"],
                    "key": l["key"],
                    "note": l["note"] or "",
                    "created_at": l["created_at"],
                    "expires_at": l["expires_at"],
                    "hwid": l["hwid"],
                    "bound": bool(l["hwid"]),
                    "status": st
                }
        return {
            "id": u["id"],
            "name": u["name"],
            "email": u["email"],
            "avatar": u["avatar"] or "",
            "discord": u["discord"] or "",
            "created_at": u["created_at"],
            "last_login": u["last_login"],
            "license": lic
        }

    @app.errorhandler(Exception)
    def on_error(e):
        if isinstance(e, HTTPException):
            return e
        traceback.print_exc()  # Details erscheinen im Server-Fenster
        detail = f"{type(e).__name__}: {e}" if session.get("admin") else "Interner Fehler."
        return f"Fehler: {detail}", 500

    def admin_required(fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            admin_name = session.get("admin_user") or ADMIN_USER
            with db() as c:
                admin = c.execute("SELECT is_active FROM admins WHERE username=? COLLATE NOCASE", (admin_name,)).fetchone()
            if not session.get("admin") or not admin or not admin["is_active"]:
                session.clear()
                return redirect("/admin/login")
            if request.method == "POST":
                if not hmac.compare_digest(request.form.get("csrf", ""), session.get("csrf", "")):
                    abort(400)
            return fn(*a, **kw)

        return wrapper

    def api_admin_required(fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            auth = request.headers.get("Authorization", "")
            tok = auth.replace("Bearer ", "").strip() if auth.startswith("Bearer ") else None
            if not tok and session.get("admin"):
                admin_name = session.get("admin_user") or ADMIN_USER
                with db() as c:
                    admin = c.execute("SELECT is_active FROM admins WHERE username=? COLLATE NOCASE", (admin_name,)).fetchone()
                if admin and admin["is_active"]:
                    g.admin_user = admin_name
                    return fn(*a, **kw)
            else:
                admin_name = verify_token(tok)
            if not admin_name:
                return jsonify(success=False, error="Nicht autorisiert oder Sitzung abgelaufen."), 401
            g.admin_user = admin_name
            return fn(*a, **kw)

        return wrapper

    def api_admin_manager_required(fn):
        @wraps(fn)
        def wrapper(*a, **kw):
            with db() as c:
                admin = c.execute(
                    "SELECT is_superadmin FROM admins WHERE username=? COLLATE NOCASE",
                    (g.admin_user,),
                ).fetchone()
            if not admin or not admin["is_superadmin"]:
                return jsonify(success=False, error="Nur der Hauptadministrator darf Admin-Konten verwalten."), 403
            return fn(*a, **kw)
        return wrapper

    # ───── Client-API ─────
    @app.get("/api/ping")
    def api_ping():
        return jsonify(status="ok", name="REVOLT OPTIMIZER Server", version="2.0")

    @app.post("/api/validate")
    def validate():
        if rate_limited("api:" + str(request.remote_addr)):
            return jsonify(valid=False, error="Zu viele Anfragen, bitte warten."), 429
        data = request.get_json(silent=True) or {}
        key = str(data.get("key", "")).strip().upper()
        hwid = str(data.get("hwid", ""))[:128]
        if not KEY_RE.match(key) or not hwid:
            return jsonify(valid=False, error="Ungültiger Lizenzkey."), 400
        now = int(time.time())
        with db() as c:
            row = c.execute("SELECT * FROM licenses WHERE key=?", (key,)).fetchone()
            if not row:
                return jsonify(valid=False, error="Lizenzkey nicht gefunden."), 403
            if row["revoked"]:
                return jsonify(valid=False, error="Dieser Key wurde gesperrt."), 403
            if row["expires_at"] and row["expires_at"] < now:
                return jsonify(valid=False, error="Dieser Key ist abgelaufen."), 403
            if row["hwid"] and row["hwid"] != hwid:
                return jsonify(valid=False, error="Key ist an einen anderen PC gebunden."), 403
            c.execute("UPDATE licenses SET hwid=COALESCE(hwid, ?), last_seen=? WHERE id=?",
                      (hwid, now, row["id"]))
        return jsonify(valid=True, expires_at=row["expires_at"])

    # ───── REST-API für Web-Adminpanel (lizenzverwaltung.html) ─────
    @app.post("/api/admin/login")
    def api_admin_login():
        if rate_limited("login:" + str(request.remote_addr)):
            return jsonify(success=False, error="Zu viele Versuche, bitte kurz warten."), 429
        data = request.get_json(silent=True) or {}
        u = str(data.get("user", "")).strip()
        p = str(data.get("password", ""))
        with db() as c:
            admin = c.execute("SELECT * FROM admins WHERE username=? COLLATE NOCASE", (u,)).fetchone()
        if admin and admin["is_active"] and verify_password(p, admin["password_hash"]):
            tok = make_token(admin["username"])
            session.clear()
            session["admin"] = True
            session["admin_user"] = admin["username"]
            session["csrf"] = secrets.token_hex(16)
            return jsonify(success=True, token=tok, user=admin["username"],
                           is_superadmin=bool(admin["is_superadmin"]), expires_in=7 * 86400)
        return jsonify(success=False, error="Falscher Benutzername oder Passwort."), 401

    @app.get("/api/admin/admins")
    @api_admin_required
    @api_admin_manager_required
    def api_admin_admins_list():
        with db() as c:
            rows = c.execute("SELECT id,username,is_active,is_superadmin,created_at FROM admins ORDER BY id ASC").fetchall()
        admins = [{
            "id": row["id"], "username": row["username"],
            "is_active": bool(row["is_active"]), "is_superadmin": bool(row["is_superadmin"]),
            "created_at": row["created_at"],
            "is_self": row["username"].casefold() == g.admin_user.casefold(),
        } for row in rows]
        return jsonify(success=True, admins=admins)

    @app.get("/api/admin/me")
    @api_admin_required
    def api_admin_me():
        with db() as c:
            admin = c.execute("SELECT username,is_superadmin FROM admins WHERE username=? COLLATE NOCASE",
                              (g.admin_user,)).fetchone()
        if not admin:
            return jsonify(success=False, error="Admin nicht gefunden."), 404
        return jsonify(success=True, username=admin["username"], is_superadmin=bool(admin["is_superadmin"]))

    @app.post("/api/admin/admins")
    @api_admin_required
    @api_admin_manager_required
    def api_admin_admins_create():
        data = request.get_json(silent=True) or {}
        username = str(data.get("username", "")).strip()
        if not re.fullmatch(r"[A-Za-z0-9_.-]{3,32}", username):
            return jsonify(success=False, error="Der Adminname muss 3–32 Zeichen haben (Buchstaben, Zahlen, Punkt, _ oder -)."), 400
        password = "revolt-" + "".join(secrets.choice("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789") for _ in range(12))
        try:
            with db() as c:
                c.execute(
                    "INSERT INTO admins(username,password_hash,is_active,created_at) VALUES(?,?,1,?)",
                    (username, hash_password(password), int(time.time())),
                )
        except sqlite3.IntegrityError:
            return jsonify(success=False, error="Dieser Adminname ist bereits vergeben."), 409
        return jsonify(success=True, username=username, temporary_password=password)

    @app.put("/api/admin/admins/<int:admin_id>")
    @api_admin_required
    @api_admin_manager_required
    def api_admin_admins_update(admin_id):
        data = request.get_json(silent=True) or {}
        username = str(data.get("username", "")).strip()
        password = str(data.get("password", ""))
        if not re.fullmatch(r"[A-Za-z0-9_.-]{3,32}", username):
            return jsonify(success=False, error="Der Adminname muss 3–32 Zeichen haben (Buchstaben, Zahlen, Punkt, _ oder -)."), 400
        if password and (len(password) < 8 or len(password) > 128):
            return jsonify(success=False, error="Ein neues Adminpasswort muss 8 bis 128 Zeichen lang sein."), 400
        with db() as c:
            admin = c.execute("SELECT * FROM admins WHERE id=?", (admin_id,)).fetchone()
            if not admin:
                return jsonify(success=False, error="Admin nicht gefunden."), 404
            try:
                if password:
                    c.execute("UPDATE admins SET username=?,password_hash=? WHERE id=?",
                              (username, hash_password(password), admin_id))
                else:
                    c.execute("UPDATE admins SET username=? WHERE id=?", (username, admin_id))
            except sqlite3.IntegrityError:
                return jsonify(success=False, error="Dieser Adminname ist bereits vergeben."), 409
        changed_self = admin["username"].casefold() == g.admin_user.casefold()
        response = {"success": True, "username": username}
        if changed_self and admin["username"] != username:
            response["token"] = make_token(username)
        return jsonify(response)

    @app.post("/api/admin/admins/<int:admin_id>/toggle")
    @api_admin_required
    @api_admin_manager_required
    def api_admin_admins_toggle(admin_id):
        with db() as c:
            admin = c.execute("SELECT id,username,is_active FROM admins WHERE id=?", (admin_id,)).fetchone()
            if not admin:
                return jsonify(success=False, error="Admin nicht gefunden."), 404
            if admin["username"].casefold() == g.admin_user.casefold():
                return jsonify(success=False, error="Dein eigenes Admin-Konto kannst du hier nicht sperren."), 400
            active = 0 if admin["is_active"] else 1
            if not active:
                active_count = c.execute("SELECT COUNT(*) FROM admins WHERE is_active=1").fetchone()[0]
                if active_count <= 1:
                    return jsonify(success=False, error="Der letzte aktive Admin muss bestehen bleiben."), 400
            c.execute("UPDATE admins SET is_active=? WHERE id=?", (active, admin_id))
        return jsonify(success=True, is_active=bool(active))

    @app.delete("/api/admin/admins/<int:admin_id>")
    @api_admin_required
    @api_admin_manager_required
    def api_admin_admins_delete(admin_id):
        with db() as c:
            admin = c.execute("SELECT id,username,is_active FROM admins WHERE id=?", (admin_id,)).fetchone()
            if not admin:
                return jsonify(success=False, error="Admin nicht gefunden."), 404
            if admin["username"].casefold() == g.admin_user.casefold():
                return jsonify(success=False, error="Dein eigenes Admin-Konto kannst du nicht löschen."), 400
            if admin["is_active"]:
                active_count = c.execute("SELECT COUNT(*) FROM admins WHERE is_active=1").fetchone()[0]
                if active_count <= 1:
                    return jsonify(success=False, error="Der letzte aktive Admin muss bestehen bleiben."), 400
            c.execute("DELETE FROM admins WHERE id=?", (admin_id,))
