    @app.get("/api/admin/users")
    @api_admin_required
    def api_admin_users_list():
        now = int(time.time())
        with db() as c:
            rows = c.execute("""SELECT u.id,u.name,u.email,u.created_at,u.last_login,u.discord,
                               u.license_id,u.is_active,l.key,l.expires_at,l.revoked
                               FROM users u LEFT JOIN licenses l ON l.id=u.license_id
                               ORDER BY u.id DESC""").fetchall()
        users = []
        for row in rows:
            license_info = None
            if row["license_id"] and row["key"]:
                status = "gesperrt" if row["revoked"] else (
                    "abgelaufen" if row["expires_at"] and row["expires_at"] < now else "aktiv")
                license_info = {"key": row["key"], "status": status, "expires_at": row["expires_at"]}
            users.append({
                "id": row["id"], "name": row["name"], "email": row["email"],
                "created_at": row["created_at"], "last_login": row["last_login"],
                "discord": row["discord"] or "", "is_active": bool(row["is_active"]),
                "status": "aktiv" if row["is_active"] else "gesperrt", "license": license_info,
            })
        return jsonify(success=True, users=users, stats={
            "total": len(users), "active": sum(u["is_active"] for u in users),
            "suspended": sum(not u["is_active"] for u in users),
        })

    @app.post("/api/admin/users/bulk")
    @api_admin_required
    def api_admin_users_bulk():
        data = request.get_json(silent=True) or {}
        action = str(data.get("action", ""))
        raw_ids = data.get("ids")
        if action not in {"activate", "suspend", "delete"}:
            return jsonify(success=False, error="Ungültige Mehrfachaktion."), 400
        if not isinstance(raw_ids, list) or not raw_ids or len(raw_ids) > 500:
            return jsonify(success=False, error="Bitte wähle 1 bis 500 Konten aus."), 400
        if any(isinstance(value, bool) or not isinstance(value, int) or value <= 0 for value in raw_ids):
            return jsonify(success=False, error="Ungültige Kontoauswahl."), 400
        user_ids = sorted(set(raw_ids))
        placeholders = ",".join("?" for _ in user_ids)
        with db() as c:
            if action == "delete":
                result = c.execute(f"DELETE FROM users WHERE id IN ({placeholders})", user_ids)
            else:
                active = 1 if action == "activate" else 0
                result = c.execute(
                    f"UPDATE users SET is_active=? WHERE id IN ({placeholders})",
                    [active, *user_ids],
                )
        return jsonify(success=True, affected=result.rowcount)

