    # ───── Kunden-Portal API (/api/auth, /api/me, /api/download) ─────
    @app.post("/api/auth/challenge")
    def api_auth_challenge():
        if rate_limited("regchallenge:" + str(request.remote_addr)):
            return jsonify(success=False, error="Zu viele Sicherheitsfragen angefordert. Bitte kurz warten."), 429
        operations = ["+", "−", "×"]
        operation = secrets.choice(operations)
        if operation == "+":
            left, right = secrets.randbelow(19) + 2, secrets.randbelow(19) + 2
            answer = left + right
        elif operation == "−":
            left, right = secrets.randbelow(18) + 10, secrets.randbelow(8) + 2
            answer = left - right
        else:
            left, right = secrets.randbelow(8) + 2, secrets.randbelow(8) + 2
            answer = left * right
        challenge_id = secrets.token_urlsafe(24)
        now = int(time.time())
        with db() as c:
            c.execute("DELETE FROM registration_challenges WHERE expires_at<=? OR attempts>=5", (now,))
            c.execute(
                "INSERT INTO registration_challenges(id,answer_hash,attempts,created_at,expires_at) VALUES(?,?,0,?,?)",
                (challenge_id, registration_challenge_hash(challenge_id, str(answer)), now, now + 300),
            )
        response = jsonify(success=True, challenge_id=challenge_id, prompt=f"Was ergibt {left} {operation} {right}?", expires_in=300)
        response.headers["Cache-Control"] = "no-store"
        return response

    @app.post("/api/auth/register")
    def api_auth_register():
        if rate_limited("reg:" + str(request.remote_addr)):
            return jsonify(success=False, error="Zu viele Versuche, bitte kurz warten."), 429
        data = request.get_json(silent=True) or {}
        name = str(data.get("name", "")).strip()[:40]
        email = str(data.get("email", "")).strip().lower()[:100]
        password = str(data.get("password", ""))
        challenge_id = str(data.get("challenge_id", "")).strip()[:128]
        answer = str(data.get("challenge_answer", "")).strip()
        honeypot = str(data.get("website", "")).strip()
        if honeypot:
            return jsonify(success=False, error="Die Registrierung konnte nicht verarbeitet werden."), 400
        if not name:
            return jsonify(success=False, error="Bitte einen Namen eingeben."), 400
        if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
            return jsonify(success=False, error="Bitte eine gültige E-Mail-Adresse eingeben."), 400
        if len(password) < 8 or len(password) > 128:
            return jsonify(success=False, error="Das Passwort muss 8 bis 128 Zeichen lang sein."), 400
        if not challenge_id or not re.fullmatch(r"\d{1,3}", answer):
            return jsonify(success=False, error="Bitte beantworte zuerst die Sicherheitsfrage."), 400
        now = int(time.time())
        try:
            with db() as c:
                c.execute("DELETE FROM registration_challenges WHERE expires_at<=?", (now,))
                challenge = c.execute("SELECT * FROM registration_challenges WHERE id=?", (challenge_id,)).fetchone()
                if not challenge:
                    return jsonify(success=False, error="Die Sicherheitsfrage ist abgelaufen. Lade bitte eine neue."), 400
                if challenge["attempts"] >= 5:
                    return jsonify(success=False, error="Zu viele falsche Antworten. Lade bitte eine neue Sicherheitsfrage."), 429
                answer_hash = registration_challenge_hash(challenge_id, answer)
                if not hmac.compare_digest(answer_hash, challenge["answer_hash"]):
                    c.execute("UPDATE registration_challenges SET attempts=attempts+1 WHERE id=?", (challenge_id,))
                    return jsonify(success=False, error="Die Antwort auf die Sicherheitsfrage ist falsch."), 400
                c.execute("DELETE FROM registration_challenges WHERE id=?", (challenge_id,))
                existing = c.execute("SELECT 1 FROM users WHERE email=? COLLATE NOCASE", (email,)).fetchone()
                if existing:
                    return jsonify(success=False, error="Diese E-Mail-Adresse ist bereits registriert."), 409
                cur = c.execute(
                    "INSERT INTO users(name,email,password_hash,created_at,last_login) VALUES(?,?,?,?,?)",
                    (name, email, hash_password(password), now, now),
                )
                uid = cur.lastrowid
                user = c.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()
        except sqlite3.IntegrityError:
            return jsonify(success=False, error="Diese E-Mail-Adresse ist bereits registriert."), 409
        return jsonify(success=True, token=make_user_token(uid), user=serialize_user(dict(user)))

    @app.post("/api/auth/login")
    def api_auth_login():
        if rate_limited("userlogin:" + str(request.remote_addr)):
            return jsonify(success=False, error="Zu viele Versuche, bitte kurz warten."), 429
        data = request.get_json(silent=True) or {}
        email = str(data.get("email", "")).strip().lower()
        password = str(data.get("password", ""))
        if not email or not password:
            return jsonify(success=False, error="Bitte E-Mail und Passwort eingeben."), 400
        with db() as c:
            u = c.execute("SELECT * FROM users WHERE email=?", (email,)).fetchone()
        if not u or not verify_password(password, u["password_hash"]):
            return jsonify(success=False, error="Falsche E-Mail-Adresse oder falsches Passwort."), 401
        if not u["is_active"]:
            return jsonify(success=False, error="Dein Konto wurde vom Administrator gesperrt."), 403
        now = int(time.time())
        with db() as c:
            c.execute("UPDATE users SET last_login=? WHERE id=?", (now, u["id"]))
        u_dict = dict(u)
        u_dict["last_login"] = now
        tok = make_user_token(u["id"])
        return jsonify(success=True, token=tok, user=serialize_user(u_dict))

