# ═════════════════════════ LIZENZ (Client) ═════════════════════════
def get_hwid():
    try:
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Cryptography", 0,
                            winreg.KEY_READ | winreg.KEY_WOW64_64KEY) as k:
            guid = winreg.QueryValueEx(k, "MachineGuid")[0]
    except (OSError, AttributeError):
        guid = str(uuid.getnode())
    return hashlib.sha256(guid.encode()).hexdigest()[:32]


def login_website_account(email, password):
    """Prüft Website-Zugangsdaten und die mit dem Konto verknüpfte Lizenz."""
    import requests
    try:
        response = requests.post(
            f"{SERVER_URL}/api/auth/login",
            json={"email": email, "password": password}, timeout=12
        )
        data = response.json()
    except requests.RequestException:
        return False, "Website nicht erreichbar. Prüfe deine Verbindung.", None, None, None
    except ValueError:
        return False, "Ungültige Antwort von der Website.", None, None, None

    if not isinstance(data, dict):
        return False, "Ungültige Antwort von der Website.", None, None, None
    if not data.get("success"):
        return False, data.get("error", "Anmeldung fehlgeschlagen."), None, None, None

    user = data.get("user") or {}
    license_info = user.get("license")
    if not isinstance(license_info, dict) or not license_info.get("key"):
        return (False,
                "Für dieses Websitekonto ist kein Lizenzcode hinterlegt. "
                "Verknüpfe zuerst einen Code in deinem Website-Profil.",
                None, None, None)

    key = str(license_info["key"]).strip().upper()
    try:
        response = requests.post(
            f"{SERVER_URL}/api/validate",
            json={"key": key, "hwid": get_hwid()}, timeout=8
        )
        license_data = response.json()
    except requests.RequestException:
        return False, "Lizenzserver nicht erreichbar.", None, None, None
    except ValueError:
        return False, "Ungültige Antwort vom Lizenzserver.", None, None, None

    if not isinstance(license_data, dict):
        return False, "Ungültige Antwort vom Lizenzserver.", None, None, None
    if license_data.get("valid"):
        return True, "", license_data.get("expires_at"), user, key
    return (False, license_data.get("error", "Die verknüpfte Lizenz ist ungültig."),
            None, None, None)


