        def login(self):
            email = self.email_entry.get().strip().lower()
            password = self.password_entry.get()
            if not email or not password:
                self.status.configure(text="Bitte E-Mail-Adresse und Passwort eingeben.", text_color=FG)
                return
            self.btn.configure(state="disabled", text="Anmeldung wird geprüft …")
            self.status.configure(text="", text_color=MUTED)
            self.password_entry.configure(state="disabled")
            self.login_gear.configure(state="disabled")

            def work():
                result = login_website_account(email, password)
                self.after(0, lambda: self._after_login(*result))

            threading.Thread(target=work, daemon=True).start()

        def _after_login(self, ok, err, exp, user, key):
            self.password_entry.configure(state="normal")
            self.password_entry.delete(0, "end")
            self.login_gear.configure(state="normal")
            if ok:
                self.expires = exp
                self.account_user = user
                self.license_key = key
                self.show_main()
            else:
                self.btn.configure(state="normal", text="Anmelden →")
                self.status.configure(text=err, text_color=FG)

