        def _refresh_metrics(self):
            try:
                cpu = max(0.0, min(100.0, psutil.cpu_percent(interval=None)))
                ram = max(0.0, min(100.0, psutil.virtual_memory().percent))
                self.cpu_bar.set(cpu / 100)
                self.ram_bar.set(ram / 100)
                self.cpu_value.configure(text=f"{cpu:.0f}%")
                self.ram_value.configure(text=f"{ram:.0f}%")
                self.metric_hint.configure(text="SYSTEM LIVE")
                self._metrics_job = self.after(1200, self._refresh_metrics)
            except Exception:
                self._metrics_job = None

